import { BaseAgent } from '@agentforge/core';

const config = {
  name: '{{agentName}}',
  description: 'My first Agent',
  model: 'gpt-3.5-turbo',
  temperature: 0.7,
};

const agent = new BaseAgent(config);

async function main() {
  await agent.start();
  console.log('Agent started!');
}

main();

